// Synthetic inputs. The Set applies only to this execution.
const accounts = new Map([
  ["account-101", { owner: "inbound-queue", suppressed: false }],
  ["account-202", { owner: "inbound-queue", suppressed: true }],
  ["account-303", { owner: null, suppressed: false }],
]);
const signals = [
  { id: "demo-101", subject: "account-101" },
  { id: "demo-101", subject: "account-101" },
  { id: "demo-202", subject: "account-202" },
  { id: "demo-303", subject: "account-303" },
];
const source = "urn:useful-in-practice:demo-form";
const seen = new Set();

return signals.map((signal) => {
  const key = JSON.stringify([source, signal.id]);
  const account = accounts.get(signal.subject);
  let decision;
  if (seen.has(key)) {
    decision = "duplicate";
  } else if (account?.suppressed) {
    decision = "blocked";
  } else if (!account?.owner) {
    decision = "manual_review";
  } else {
    decision = "route_review_task";
  }
  seen.add(key);
  return {
    json: {
      ...signal,
      source,
      decision,
      owner: decision === "route_review_task" ? account.owner : null,
    },
  };
});
